        super(player, slot, itemStack, returnToMainMenu);
        this.craftingGrid.readFromNBT(this.getItemStack().m_41784_(), "craftingGrid");
    }

    @Override
    @Nullable
    public InternalInventory getSubInventory(ResourceLocation id) {
        if (id.equals((Object)CraftingTerminalPart.INV_CRAFTING)) {
            return this.craftingGrid;
        }
        return null;
    }

    @Override
    public void saveChanges() {
        this.craftingGrid.writeToNBT(this.getItemStack().m_41784_(), "craftingGrid");
    }

    @Override
    public void onChangeInventory(InternalInventory inv, int slot) {
    }
}

